interface.definition:
a!localVariables(
  local!isMicrobatch: ri!jobType.microbatchSize > 1,
  local!cantidadBatch: #"_a-0000ef54-29a7-8000-9ce2-011c48011c48_6841711",
  local!ejecutionInterval: #"_a-0000ef54-29a7-8000-9ce2-011c48011c48_6859470",
  {
    #"SYSTEM_SYSRULES_textField"(
      label: "Nombre",
      labelPosition: "JUSTIFIED",
      value: ri!jobType.name,
      saveInto: {
        ri!jobType.name,
        /* by default we want context to be passed */
        if(
          a!isNullOrEmpty(ri!jobType.isContextPassed),
          a!save(
            target: ri!jobType.isContextPassed,
            value: true
          ),
          {}
        )
      },
      refreshAfter: "UNFOCUS",
      required: not(ri!readOnly),
      validations: {
        if(
          len(ri!jobType.name) > 45,
          "Maximum length must not exceed 45 characters",
          null
        )
      },
      readOnly: ri!readOnly
    ),
    #"SYSTEM_SYSRULES_paragraphField"(
      label: "Descripción",
      labelPosition: "JUSTIFIED",
      value: ri!jobType.description,
      saveInto: ri!jobType.description,
      refreshAfter: "UNFOCUS",
      validations: {},
      readOnly: ri!readOnly,
      height: "MEDIUM"
    ),
    #"SYSTEM_SYSRULES_pickerFieldCustom"(
      label: "Modelo de proceso",
      labelPosition: "JUSTIFIED",
      placeholder: "Buscar un modelo de proceso",
      instructions: "Cree un modelo de proceso y configúrelo como se define en la sección Configuración de procesos a continuación",
      value: ri!jobType.modelUuid,
      saveInto: ri!jobType.modelUuid,
      selectedLabels: if(
        a!isNullOrEmpty(ri!jobType.modelUuid),
        {},
        a!defaultValue(
          #"_a-0000e3b8-7177-8000-8592-01ef9001ef90_104830"(modelUuids: ri!jobType.modelUuid),
          { name: "Process Model Not Found" }
        ).name
      ),
      suggestFunction: #"_a-0000e7da-c788-8000-d625-01ef9001ef90_29385"(filter: _),
      showWhen: not(ri!readOnly),
      required: not(ri!readOnly),
      maxSelections: 1,
      readOnly: ri!readOnly
    ),
    #"SYSTEM_SYSRULES_textField"(
      label: "Process Model",
      labelPosition: "JUSTIFIED",
      value: ri!jobType.modelUuid,
      saveInto: ri!jobType.modelUuid,
      refreshAfter: "UNFOCUS",
      showWhen: ri!readOnly,
      required: not(ri!readOnly),
      validations: {
        if(
          len(ri!jobType.modelUuid) <> 36,
          "Process Model UUID must be exactly 36 characters",
          null
        )
      },
      readOnly: ri!readOnly
    ),
    #"SYSTEM_SYSRULES_checkboxField_v1"(
      label: "¿Empiezar con el contexto?",
      labelPosition: "JUSTIFIED",
      instructions: if(
        ri!readOnly,
        "",
        "Si el proceso debe rellenar automáticamente los parámetros del proceso desde el contexto JSON de las transacciones. Si tiene un contexto grande (> 10KiB), debe desmarcar esto y recuperarlo en tiempo de ejecución dentro del proceso."
      ),
      value: if(
        or(
          ri!jobType.isContextPassed,
          a!isNullOrEmpty(ri!jobType.isContextPassed)
        ),
        true,
        null
      ),
      saveInto: {
        a!save(
          target: ri!jobType.isContextPassed,
          value: if(isnull(save!value), false, true)
        ),
        a!save(
          target: ri!jobType.microbatchSize,
          value: if(save!value, 0, ri!jobType.microbatchSize)
        )
      },
      choiceLabels: {
        "Sí, pasa el contexto al proceso que se inicia"
      },
      choiceValues: { true },
      showWhen: not(ri!readOnly)
    ),
    #"SYSTEM_SYSRULES_textField"(
      label: "Start with context?",
      labelPosition: "JUSTIFIED",
      value: if(ri!jobType.isContextPassed, "Yes", "No"),
      showWhen: ri!readOnly,
      readOnly: ri!readOnly
    ),
    #"SYSTEM_SYSRULES_sideBySideLayout"(
      items: {
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_integerField"(
            label: "Máximo funcionamiento",
            labelPosition: "JUSTIFIED",
            instructions: if(
              not(ri!readOnly),
              if(
                local!isMicrobatch,
                a!localVariables(
                  local!totalTransactions: ri!jobType.maxRunning * ri!jobType.microbatchSize,
                  "El número máximo de microlotes que se permite ejecutar en paralelo" & if(
                    local!totalTransactions > 0,
                    " (resultantes en el procesamiento" & local!totalTransactions & " transactions across " & ri!jobType.maxRunning & " microbatches).",
                    "."
                  )
                ),
                "El número máximo de transacciones que se permiten ejecutar en paralelo."
              ),
              null
            ),
            value: ri!jobType.maxRunning,
            saveInto: ri!jobType.maxRunning,
            refreshAfter: "UNFOCUS",
            required: not(ri!readOnly),
            validations: {
              if(
                ri!jobType.maxRunning < 1,
                "Debe ser al menos 1",
                null
              )
            },
            readOnly: ri!readOnly
          )
        ),
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_integerField"(
            label: "Tamaño del microlote",
            labelPosition: "JUSTIFIED",
            instructions: if(
              not(ri!readOnly),
              "Configura opcionalmente como un microlote. Esto agrupa automáticamente las transacciones del tamaño especificado. Utilice microlotes para lograr el mayor rendimiento.",
              null
            ),
            value: ri!jobType.microbatchSize,
            saveInto: {
              ri!jobType.microbatchSize,
              if(
                ri!jobType.microbatchSize > 1,
                a!save(
                  target: ri!jobType.isContextPassed,
                  value: false
                ),
                {}
              )
            },
            refreshAfter: "UNFOCUS",
            showWhen: or(
              and(ri!readOnly, local!isMicrobatch),
              not(ri!readOnly)
            ),
            validations: {
              if(
                or(
                  ri!jobType.microbatchSize = 0,
                  ri!jobType.microbatchSize > 1
                ),
                null,
                "Debe ser 0 o mayor que 1"
              )
            },
            readOnly: ri!readOnly
          )
        )
      }
    ),
    #"SYSTEM_SYSRULES_integerField"(
      label: "Tamaño del batch",
      labelPosition: "JUSTIFIED",
      instructions: if(
        not(ri!readOnly),
        "Número de correos a clasificar en cada ejecución",
        null
      ),
      value: local!cantidadBatch,
      saveInto: local!cantidadBatch,
      refreshAfter: "UNFOCUS",
      required: not(ri!readOnly),
      validations: {
        if(
          local!cantidadBatch < 1,
          "Debe ser al menos 1",
          if(
            local!cantidadBatch > 100,
            "Debe ser máximo 100",
            null
          )
        )
      },
      readOnly: ri!readOnly,
      showWhen: contains(#"_a-0000ef54-29a7-8000-9ce2-011c48011c48_6859502", ri!jobType.modelUuid)
    ),
    #"SYSTEM_SYSRULES_integerField"(
      label: "Intervalo de ejecución",
      labelPosition: "JUSTIFIED",
      instructions: if(
        not(ri!readOnly),
        "Cada cuánto tiempo en minutos se lanzará una nueva ejecución del proceso",
        null
      ),
      value: local!ejecutionInterval,
      saveInto: local!ejecutionInterval,
      refreshAfter: "UNFOCUS",
      required: not(ri!readOnly),
      validations: {
        if(
          local!ejecutionInterval < 1,
          "Debe ser al menos 1",
          null
        )
      },
      readOnly: ri!readOnly,
      showWhen: contains(#"_a-0000ef54-29a7-8000-9ce2-011c48011c48_6859502", ri!jobType.modelUuid)
    ),
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      label: "Configuración del proceso",
      contents: {
        #"SYSTEM_SYSRULES_gridField_v2"(
          label: "Parámetros del proceso",
          labelPosition: "ABOVE",
          instructions: "Cree un modelo de proceso con los siguientes parámetros de proceso",
          data: {
            {
              name: "transaction",
              dataType: "TM_Transaction",
              array: "No",
              desc: if(
                local!isMicrobatch,
                "Parámetro requerido que representa el microlote de transacciones creadas a partir de varias transacciones individuales.",
                "Parámetro requerido que representa su transacción. Se utiliza para marcar la transacción como completada."
              )
            },
            if(
              local!isMicrobatch,
              {
                name: "transactionIds",
                dataType: "Integer",
                array: "Yes",
                desc: "Required parameter that provides a list of transaction ids for each of the transactions within this microbatch."
              },
              {}
            ),
            if(
              local!isMicrobatch,
              {
                name: "Sin parámetros de proceso adicionales",
                dataType: "n/a",
                array: "n/a",
                desc: "Los parámetros de proceso adicionales que definió NO se rellenarán."
              },
              {
                name: "Los parámetros de su proceso",
                dataType: "-",
                array: "-",
                desc: "Agregue parámetros de proceso para que coincidan con su contexto."
              }
            )
          },
          columns: {
            #"SYSTEM_SYSRULES_gridColumn"(
              label: "Name",
              value: fv!row.name,
              width: "MEDIUM"
            ),
            #"SYSTEM_SYSRULES_gridColumn"(
              label: "Tipo de datos",
              value: fv!row.dataType,
              width: "NARROW"
            ),
            #"SYSTEM_SYSRULES_gridColumn"(
              label: "Múltiples",
              value: fv!row.array,
              width: "NARROW"
            ),
            #"SYSTEM_SYSRULES_gridColumn"(label: "Descripción", value: fv!row.desc)
          }
        ),
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          label: "Nodos de proceso",
          labelPosition: "ABOVE",
          value: {
            "Como cada instancia de proceso individual procesará una sola transacción, utilice los parámetros del proceso como con cualquier otro proceso para realizar los pasos requeridos.",
            char(10),
            "Antes de que finalice su proceso, use un subproceso para ejecutar TM Marque la transacción como completa pasando el parámetro de proceso de transacción como una entrada."
          },
          showWhen: not(local!isMicrobatch)
        ),
        #"SYSTEM_SYSRULES_richTextDisplayField"(
          label: "Process Nodes",
          labelPosition: "ABOVE",
          value: {
            "As each individual process instance will process ",
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: { "a microbatch of several transactions" },
              style: { "STRONG" }
            ),
            " use the ",
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: { "transactionIds " },
              style: { "EMPHASIS" }
            ),
            "parameter to retrieve the context you require from ",
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: { "tm_transaction" },
              style: { "EMPHASIS" }
            ),
            " table.",
            char(10),
            char(10),
            "Before your process ends use a subprocess to execute ",
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: { "TM Mark Transactions as Complete " },
              style: { "STRONG" }
            ),
            "passing ",
            #"SYSTEM_SYSRULES_richTextItem_v1"(text: { "both " }, style: { "STRONG" }),
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: { "transaction " },
              style: { "EMPHASIS" }
            ),
            "and ",
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: { "transactionIds" },
              style: { "EMPHASIS" }
            ),
            " process parameter as an input. As in - ",
            #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: {
                "=append(pv!transactionIds, pv!transaction.id)"
              },
              color: "#666666"
            )
          },
          showWhen: local!isMicrobatch
        )

      },
      showWhen: not(ri!readOnly),
      isCollapsible: true
    ),
    #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: #"SYSTEM_SYSRULES_buttonWidget_v1"(
        label: "Update",
        saveInto: {
          a!save(target: ri!readOnly, value: true),
          #"SYSTEM_SYSRULES_startProcess"(
            processModel: #"_a-0000e470-9a48-8000-8592-01ef9001ef90_107007",
            processParameters: {
              jobType: ri!jobType,
              batchSize: local!cantidadBatch,
              ejecutionInterval: local!ejecutionInterval
            }
          )
        },
        style: "SOLID"
      ),
      secondaryButtons: #"SYSTEM_SYSRULES_buttonWidget_v1"(
        label: "Cancel",
        saveInto: a!save(target: ri!readOnly, value: true),
        style: "OUTLINE"
      ),
      showWhen: and(
        not(ri!readOnly),
        contains(#"_a-0000ef54-29a7-8000-9ce2-011c48011c48_6859502", ri!jobType.modelUuid)
      )
    ),
    #"SYSTEM_SYSRULES_ButtonLayout"(
      primaryButtons: #"SYSTEM_SYSRULES_buttonWidget_v1"(
        label: "Añadir tipo de trabajo",
        saveInto: a!save(target: ri!jobType.isActive, value: true),
        submit: true,
        style: "SOLID"
      ),
      secondaryButtons: #"SYSTEM_SYSRULES_buttonWidget_v1"(
        label: "Cancelar",
        saveInto: a!save(target: ri!isCancel, value: true),
        validate: false,
        submit: true
      ),
      showWhen: or(
        isnull(ri!recordContext),
        not(ri!recordContext)
      )
    )
  }
)
